using Swashbuckle.AspNetCore.Annotations;namespace GraphApi.Models.ARC.TiposArchivo{    [SwaggerSchema("Modelo de lectura de un TiposArchivo")]    [GraphQLDescription("Objeto que representa un TiposArchivo existente.")]    public class clReadTiposArchivo    {        [SwaggerSchema("Identificador único del TiposArchivo")]        [GraphQLDescription("Identificador único del TiposArchivo")]        public int? TipoArchivoID { get; set; }        [SwaggerSchema("TipoArchivo")]        [GraphQLDescription("TipoArchivo")]        public string? TipoArchivo { get; set; } = default!;        [SwaggerSchema("bEliminado")]        [GraphQLDescription("bEliminado")]        public bool? bEliminado { get; set; }    }    [SwaggerSchema("Modelo de creación de un TiposArchivo")]    [GraphQLDescription("Input para crear un TiposArchivo.")]    public class clCreateTiposArchivo    {        [GraphQLNonNullType] [SwaggerSchema("TipoArchivo")]        [GraphQLDescription("TipoArchivo")]        public string TipoArchivo { get; set; } = default!;        [GraphQLNonNullType] [SwaggerSchema("bEliminado")]        [GraphQLDescription("bEliminado")]        public bool bEliminado { get; set; }    }    [SwaggerSchema("Modelo de actualización de un TiposArchivo")]    [GraphQLDescription("Input para actualizar parcialmente un TiposArchivo.")]    public class clUpdateTiposArchivo    {        [SwaggerSchema("Identificador único del TiposArchivo")]        [GraphQLDescription("Identificador único del TiposArchivo")]        public int? TipoArchivoID { get; set; }        [SwaggerSchema("TipoArchivo")]        [GraphQLDescription("TipoArchivo")]        public string? TipoArchivo { get; set; }        [SwaggerSchema("bEliminado")]        [GraphQLDescription("bEliminado")]        public bool? bEliminado { get; set; }    }}